import React, { useEffect, useState } from "react";
import "./../css/bot.css";
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import TimePicker from 'react-time-picker';
import BarChart from "./BloodAvailability";

function Home() {
  useEffect(() => {
    const chatForm = document.getElementById("chat-form");
    const chatInput = document.getElementById("chat-input");
    const chatLogs = document.querySelector(".chat-logs");

    const handleSubmit = async (event) => {
      event.preventDefault();

      const userPrompt = chatInput.value.trim();

      if (!userPrompt) {
        return; // Don't proceed if the input is empty
      }

      // Display user message in the chat log
      displayUserMessage(userPrompt);

      try {
        // Call the Flask API chatbot
        const response = await fetch("http://localhost:5001/chatbot", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ user_prompt: userPrompt }),
        });

        if (response.ok) {
          const data = await response.json();
          // Display bot's response in the chat log
          displayBotResponse(data.response);
        } else {
          console.error("Error fetching response from API");
        }
      } catch (error) {
        console.error("Error:", error);
      }

      // Clear the input
      chatInput.value = "";
    };

    const displayUserMessage = (message) => {
      const chatLog = document.createElement("div");
      chatLog.className = "chat-msg user";
      chatLog.innerHTML = `<div class="cm-msg-text">${message}</div>`;
      chatLogs.appendChild(chatLog);
    };

    const displayBotResponse = (response) => {
      const chatLog = document.createElement("div");
      chatLog.className = "chat-msg self";
      chatLog.innerHTML = `<div class="cm-msg-text">${response}</div>`;
      chatLogs.appendChild(chatLog);
    };


    chatForm.addEventListener("submit", handleSubmit);

    // Cleanup function
    return () => {
      chatForm.removeEventListener("submit", handleSubmit);
    };
  }, []); // Empty dependency array for componentDidMount behavior




  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [userLocation, setUserLocation] = useState(null);
  const [searchResultsTable, setSearchResultsTable] = useState([]);

  const handleInputChange = (e) => {
    const searchTerm = e.target.value;
    setSearchTerm(searchTerm);

    if (searchTerm.trim() === "") {
      setSearchResults([]);
    } else {
      const results = services
        .filter((service) =>
          service.hsServices.toLowerCase().includes(searchTerm.toLowerCase())
        )
        .reduce((uniqueResults, service) => {
          // Check if the service is already in uniqueResults
          if (
            !uniqueResults.some(
              (result) => result.hsServices === service.hsServices
            )
          ) {
            // If not, add it to uniqueResults
            uniqueResults.push(service);
          }
          return uniqueResults;
        }, []);

      setSearchResults(results);
    }
  };

  const handleServiceSelect = (selectedService) => {
    setSelectedService(selectedService);
    setSearchTerm(selectedService.hsServices); // Populate search bar
    setSearchResults([]); // Clear search results
  };

  const handleSearch = async () => {
    if (selectedService && userLocation) {
      try {
        // Reset previous info apart from user latitude and longitude
        setSelectedService(null);
        setSearchResults([]);
        setSearchResultsTable([]);

        const response = await fetch(
          "http://localhost:5206/api/HospitalServices/Search",
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              userLatitude: userLocation.latitude,
              userLongitude: userLocation.longitude,
              service: selectedService.hsServices,
            }),
          }
        );

        if (response.ok) {
          const data = await response.json();
          // Handle the response data as needed
          console.log("Nearest Hospital:", data);
          setSearchResultsTable(data);
        } else {
          console.error("Error fetching nearest hospital from API");
          // Show an error message
          setSearchResultsTable([]);
          setSearchResults([{ hsServices: "Error fetching data" }]);
        }
      } catch (error) {
        console.error("Error:", error);
      }
    }
  };



  const SearchResultList = ({ results }) => (
    <ul className="list-group list-group-flush">
      {results.map((service, index) => (
        <li
          className="list-group-item"
          key={index}
          onClick={() => handleServiceSelect(service)}
        >
          {service.hsServices}
        </li>
      ))}
    </ul>
  );

  //call services api

  const [services, setServices] = useState([]);

  useEffect(() => {
    const fetchServices = async () => {
      try {
        const response = await fetch(
          "http://localhost:5206/api/HospitalServices"
        );

        if (response.ok) {
          const data = await response.json();
          setServices(data); // Assuming the API response is an array of services
        } else {
          console.error("Error fetching services from API");
        }
      } catch (error) {
        console.error("Error:", error);
      }
    };

    fetchServices();
  }, []);


  const SearchResultsTable = ({ results }) => (
    <div className="row mt-3">
      {results.map((result, index) => (
        <div key={index} className="col-lg-6 col-md-6">
          <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
            <div className="service-icon mb-4">
              <i className="fa fa-2x fa-user-md text-white" />
            </div>
            <h3 className="mb-3">{result.hName}</h3>
            <h5 className="m-0">{result.hAddress}</h5><br />
            <h4 className="m-0" style={{color:'red'}}>Distance: {result.distanceInKm.toFixed(2)} km</h4>

          </div>
        </div>
      ))}
    </div>
  );
  /// end services api


  useEffect(() => {
    const fetchLocation = async () => {
      try {
        const position = await getCurrentLocation();
        setUserLocation(position.coords);
      } catch (error) {
        console.error("Error getting user location:", error);
      }
    };

    fetchLocation();
  }, []);

  const getCurrentLocation = () => {
    return new Promise((resolve, reject) => {
      if ("geolocation" in navigator) {
        navigator.geolocation.getCurrentPosition(resolve, reject);
      } else {
        reject("Geolocation not available");
      }
    });
  };




    const [doctors, setDoctors] = useState([]);

    useEffect(() => {
      const fetchDoctors = async () => {
        try {
          const response = await fetch("http://localhost:5206/api/Doctors_Cr");

          if (response.ok) {
            const data = await response.json();
            setDoctors(data);
          } else {
            console.error("Error fetching doctors from API");
          }
        } catch (error) {
          console.error("Error:", error);
        }
      };

      fetchDoctors();
    }, []);

    const getOneDoctorPerHospital = () => {
      const uniqueHospitals = new Set();
      const doctorsPerHospital = [];

      doctors.forEach((doctor) => {
        if (!uniqueHospitals.has(doctor.dhId)) {
          uniqueHospitals.add(doctor.dhId);
          doctorsPerHospital.push(doctor);
        }
      });

      return doctorsPerHospital;
    };

    const doctorsList = getOneDoctorPerHospital();




    //doctors appointment

    const [dobPickerOpen, setDobPickerOpen] = useState(false);
    const [apptDatePickerOpen, setApptDatePickerOpen] = useState(false);


    const handleDOBChange = (date) => {
      setFormData((prevFormData) => ({ ...prevFormData, APatientDOB: date }));
      setDobPickerOpen(false);
    };

    const handleApptDateChange = (date) => {
      setFormData((prevFormData) => ({ ...prevFormData, ADate: date }));
      setApptDatePickerOpen(false);
    };

      const [formData, setFormData] = useState({
        APatientName: "",
        APatientDOB: "",
        ADate: "",
        ATime: "",
        ADId: "",
        AType: "",
        AMobile: "",
        AEmail: "",
        AReason: "",
      });

      const [doctorsA, setDoctorsA] = useState([]);
      const [hospitals, setHospitals] = useState([]);
      const [loading, setLoading] = useState(false);

      const fetchDoctorsA = async (dhId) => {
        try {
          const response = await fetch(`http://localhost:5206/api/Doctors_Cr/ByHospitalId/${dhId}`);
          if (response.ok) {
            const doctorList = await response.json();
            setDoctors(doctorList);
          } else {
            console.error("Failed to fetch doctors:", response.status, response.statusText);
          }
        } catch (error) {
          console.error("An error occurred while fetching doctors:", error);
        }
      };

      useEffect(() => {
        const fetchHospitalsA = async () => {
          try {
            const response = await fetch("http://localhost:5206/api/Hospital_Cr");
            if (response.ok) {
              const hospitalList = await response.json();
              setHospitals(hospitalList);
            } else {
              console.error("Failed to fetch hospitals:", response.status, response.statusText);
            }
          } catch (error) {
            console.error("An error occurred while fetching hospitals:", error);
          }
        };

        fetchHospitalsA();
      }, []);

      const handleSubmitA = async (e) => {
        e.preventDefault();
        console.log("Form submitted");

        try {
          setLoading(true);
          console.log("Form Data:", formData); // Log the form data for debugging

          // Make sure to format the date and time before sending to the server
          const formattedData = {
            ...formData,
            APatientDOB: formatDate(formData.APatientDOB),
            ADate: formatDate(formData.ADate),
            ATime: formatTime(formData.ATime),
          };

          const response = await fetch("http://localhost:5206/api/appointment_cr", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify(formattedData),
          });

          if (response.ok) {
            setFormData({
              APatientName: "",
              APatientDOB: "",
              ADate: "",
              ATime: "",
              ADId: "",
              AType: "",
              AMobile: "",
              AEmail: "",
              AReason: "",
            });
            setLoading(false);
            // Add any additional actions you want to perform after successful submission
          } else {
            console.error("Failed to create appointment:", response.status, response.statusText);
          }
        } catch (error) {
          console.error("An error occurred during form submission:", error);
          setLoading(false);
        }
      };

      const handleInputChangeA = (e) => {
        const { name, value } = e.target;

        // Convert date and time values to the desired format
        const formattedValue = name === 'APatientDOB' || name === 'ADate' ? formatDate(value) : value;

        setFormData((prevFormData) => ({ ...prevFormData, [name]: formattedValue }));

        if (name === 'ADhId') {
          setDoctors([]); // Clear the existing doctors list
          fetchDoctorsA(value);
        }
      };

      const formatDate = (dateString) => {
        const date = new Date(dateString);
        return date.toISOString().split('T')[0]; // Format as 'yyyy-mm-dd'
      };

      const formatTime = (timeString) => {
        return `${timeString}:00.0000000`;
      };



    /// appountment end



  return (
    <div>
      <div>
        <div id="body">
          <div id="chat-circle" className="btn btn-raised">
            <img
              id="chat-bot"
              src="./assets/img/chatbot.png"
              style={{ objectFit: "contain" }}
            />
          </div>
          <div className="chat-box">
            <div className="chat-box-header">
              ChatBot
              <span className="chat-box-toggle">
                <i className="material-icons">close</i>
              </span>
            </div>
            <div className="chat-box-body chatP">
              <div className="chat-box-overlay" />
              <div className="chat-logs" />
            </div>
            <div className="chat-input">
              <form id="chat-form">
                <input
                  type="text"
                  id="chat-input"
                  name="chat-input"
                  placeholder="Send a message..."
                />
                <button type="submit" className="chat-submit">
                  <i className="material-icons">Send</i>
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>




      <div className="container-fluid bg-primary py-5 mb-5 hero-header">
        <div className="container py-5">
          <div className="row justify-content-start">
            <div className="col-lg-8 text-center text-lg-start">
              <h5
                className="d-inline-block text-primary text-uppercase border-bottom border-5"
                style={{ borderColor: "rgba(256, 256, 256, .3) !important" }}
              >
                Welcome To LifeLine
              </h5>
              <h1 className="display-1 text-white mb-md-4">
                Get instant help from our AI
              </h1>
              <div className="pt-2">
              </div>
            </div>
          </div>
        </div>
      </div>
      <div>


        <div className="container-fluid py-5">
          <div className="container">
            <div className="text-center mx-auto mb-5" style={{ maxWidth: 500 }}>
              <h5 className="d-inline-block text-primary text-uppercase border-bottom border-5">
                Services
              </h5>
              <h1 className="display-4">Excellent Services</h1>
            </div>
            <div className="row g-5">
              <div className="col-lg-4 col-md-6">
                <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
                  <div className="service-icon mb-4">
                    <i className="fa fa-2x fa-user-md text-white" />
                  </div>
                  <h4 className="mb-3">Find Nearest Hospital</h4>
                  <p className="m-0">
                  Find the nearest hospital offering services you want for your loved ones.
                  </p>

                </div>
              </div>
              <div className="col-lg-4 col-md-6">
                <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
                  <div className="service-icon mb-4">
                    <i className="fa fa-2x fa-procedures text-white" />
                  </div>
                  <h4 className="mb-3">Blood Availability Prediction</h4>
                  <p className="m-0">
                  Need blood urgently but don't know where to go? Not to worry, our AI powered blood availability prediction has got you covered.
                  </p>

                </div>
              </div>
              <div className="col-lg-4 col-md-6">
                <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
                  <div className="service-icon mb-4">
                    <i className="fa fa-2x fa-stethoscope text-white" />
                  </div>
                  <h4 className="mb-3">Appointment</h4>
                  <p className="m-0">
                  Need to have a checkup? Our Insanely Fast Appointment feature allows you to schedule appointments with the best hospitals in your city.
                  </p>

                </div>
              </div>
              <div className="col-lg-4 col-md-6">
                <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
                  <div className="service-icon mb-4">
                    <i className="fa fa-2x fa-ambulance text-white" />
                  </div>
                  <h4 className="mb-3">AI powered Chatbot</h4>
                  <p className="m-0">
                  Feeling ill? Don't worry, our chatbot has got you covered. Trained on over 130 diseases, find out symptoms and possible ways to cure it.
                  </p>

                </div>
              </div>
              <div className="col-lg-4 col-md-6">
                <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
                  <div className="service-icon mb-4">
                    <i className="fa fa-2x fa-pills text-white" />
                  </div>
                  <h4 className="mb-3">Medical Portfolio</h4>
                  <p className="m-0">
                  Review your overall medical history in a beautiful and attractive medical portfolio generated through our powerful AI.
                  </p>

                </div>
              </div>
              <div className="col-lg-4 col-md-6">
                <div className="service-item bg-light rounded d-flex flex-column align-items-center justify-content-center text-center">
                  <div className="service-icon mb-4">
                    <i className="fa fa-2x fa-microscope text-white" />
                  </div>
                  <h4 className="mb-3">Video Appointment</h4>
                  <p className="m-0">
                  Have an appointment but cant't make it to the hospital? Dont worry, our portal provides Video Calling feature which allows you to connect with your doctor within seconds.
                  </p>

                </div>
              </div>
            </div>
          </div>
        </div>
        <BarChart />

        <div className="container-fluid bg-primary my-5 py-5">
          <div className="container py-5">
            <div className="row gx-5">
              <div className="col-lg-6 mb-5 mb-lg-0">
                <div className="mb-4">
                  <h5 className="d-inline-block text-white text-uppercase border-bottom border-5">
                    Appointment
                  </h5>
                  <h1 className="display-4">
                    Make An Appointment
                  </h1>
                </div>
                <p className="text-white mb-5">
                Medicine, an evolving tapestry of scientific breakthroughs and timeless wisdom, transcends epochs. From the ancient remedies passed through oral traditions to the cutting-edge technologies unveiling the secrets of our DNA, it's a continuum of innovation. Yet, amidst this progress, the essence remains constant—the commitment to relieve pain, restore health, and enhance the quality of life for every individual. It's a journey where past, present, and future intersect for the betterment of humanity.
                </p>

              </div>



              <div className="col-lg-6">
      <div className="bg-white text-center rounded p-5">
        <h1 className="mb-4">Book An Appointment</h1>
        <form onSubmit={handleSubmitA}>
          <div className="row g-3">
            <div className="col-12">
              <input
                type="text"
                className="form-control bg-light border-0"
                placeholder="Your Name"
                style={{ height: 55 }}
                name="APatientName"
                value={formData.APatientName}
                onChange={handleInputChangeA}
              />
            </div>
            <div className="col-12">
              <DatePicker
                selected={formData.APatientDOB}
                className="form-control bg-light border-0"
                onChange={handleDOBChange}
                placeholderText="Date Of Birth (mm/dd/yyyy)"
                dateFormat="MM/dd/yyyy"
                peekNextMonth
                showMonthDropdown
                showYearDropdown
                dropdownMode="select"
                maxDate={new Date()}
              />
            </div>
            <div className="col-12">
              <DatePicker
                selected={formData.ADate}
                onChange={handleApptDateChange}
                className="form-control bg-light border-0"
                placeholderText="Select Appointment Date (mm/dd/yyyy)"
                dateFormat="MM/dd/yyyy"
                peekNextMonth
                showMonthDropdown
                showYearDropdown
                dropdownMode="select"
                minDate={new Date()}
              />
            </div>
            <div className="col-12">
  <TimePicker
    className="form-control bg-light border-0"
    onChange={(time) => setFormData((prevFormData) => ({ ...prevFormData, ATime: time }))}
    value={formData.ATime}
    format="HH:mm"
    clearIcon={null} // To hide the clear icon
    style={{ fontSize: '16px', width: '100%' }} // Adjust the font size and width as needed
  />
</div>
            <div className="col-12">
              <select
                className="form-select bg-light border-0"
                style={{ height: 55 }}
                name="ahId"
                value={formData.ahId}
                onChange={handleInputChangeA}
              >
                <option selected>Select Hospital</option>
                {hospitals.map((hospital) => (
                  <option key={hospital.hId} value={hospital.hId}>
                    {hospital.hName}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-12">
              <select
                className="form-select bg-light border-0"
                style={{ height: 55 }}
                name="ADId"
                value={formData.ADId}
                onChange={handleInputChangeA}
              >
                <option selected>Select Doctor</option>
                {doctors.map((doctor) => (
                  <option key={doctor.dId} value={doctor.dId}>
                    {doctor.dName}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-12">
              <input
                type="text"
                className="form-control bg-light border-0"
                placeholder="Select Appointment Type"
                style={{ height: 55 }}
                name="AType"
                value={formData.AType}
                onChange={handleInputChangeA}
              />
            </div>
            <div className="col-12">
              <input
                type="tel"
                className="form-control bg-light border-0"
                placeholder="Contact No."
                style={{ height: 55 }}
                name="AMobile"
                value={formData.AMobile}
                onChange={handleInputChangeA}
              />
            </div>
            <div className="col-12">
              <input
                type="email"
                className="form-control bg-light border-0"
                placeholder="Your Email"
                style={{ height: 55 }}
                name="AEmail"
                value={formData.AEmail}
                onChange={handleInputChangeA}
              />
            </div>
            <div className="col-12">
              <textarea
                className="form-control bg-light border-0"
                placeholder="Appointment Reason"
                style={{ height: 100 }}
                name="AReason"
                value={formData.AReason}
                onChange={handleInputChangeA}
              ></textarea>
            </div>
            <div className="col-12">
              <button
                className="btn btn-primary w-100 py-3"
                type="submit"
              >
                Make An Appointment
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>

            </div>
          </div>
        </div>









      <div className="container-fluid bg-primary my-5 py-5">
      <div className="text-center mx-auto mb-5" style={{ maxWidth: 500 }}>
              <h5 className="d-inline-block text-uppercase border-bottom border-5">
                Find
              </h5>
              <h1 className="display-4">Nearest Hospital With the Service you wish to avail</h1>
            </div>
        <div className="container py-5">
          <div
            className="mx-auto"
            style={{ width: "100%", maxWidth: 600 }}
          >
            <div className="input-group">
              <input
                type="text"
                className="form-control border-primary w-75"
                placeholder="Search..."
                value={searchTerm}
                onChange={handleInputChange}
              />
              <button
                type="button"
                className="btn btn-dark border-0 w-25"
                onClick={handleSearch}
              >
                Search
              </button>
            </div>
            <div className="mt-3">
              {searchTerm !== "" && searchResults.length > 0 && (
                <div className="card">
                  <div className="card-body p-0">
                    <SearchResultList results={searchResults} />
                  </div>
                </div>
              )}
              {/* {searchTerm !== "" && searchResults.length === 0 && (
                <h4 style={{color:'red'}}>No results found</h4>
              )} */}
            </div>
          </div>
            <div className="mt-9" style={{display:'flex'}}>
              {searchTerm !== "" && searchResultsTable.length > 0 && (
                <SearchResultsTable results={searchResultsTable} />
              )}
            </div>
        </div>
      </div>




        <a
          href="#"
          className="btn btn-lg btn-primary btn-lg-square back-to-top"
        >
          <i className="bi bi-arrow-up" />
        </a>
      </div>
    </div>


  );
}

export default Home;
